sparql_response:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?film ?country WHERE {
  VALUES ?film { 
    <http://dbpedia.org/resource/Supercock> 
    <http://dbpedia.org/resource/Intelligence_and_the_Japanese_Civilian>
  }
  OPTIONAL { ?film dbo:country ?c1 . }
  OPTIONAL { ?film dbp:country ?c2 . }
  BIND (COALESCE(?c1, ?c2) AS ?country)
}
LIMIT 100

